const form=document.querySelector('#notice-form'),publish=document.querySelector('#publish'),status=document.querySelector('#notice-status'),preview=document.querySelector('#notice-preview');let draft=null;
form.addEventListener('input',()=>{draft=null;publish.disabled=true;status.textContent='Draft changed · Preview again before publishing.'});
form.onsubmit=e=>{e.preventDefault();draft={title:document.querySelector('#notice-title').value.trim(),text:document.querySelector('#notice-message').value.trim(),priority:document.querySelector('#notice-priority').value};if(!draft.title||!draft.text){status.textContent='Enter a title and rider message.';return}preview.hidden=false;preview.textContent=`${draft.priority.toUpperCase()} · ${draft.title}: ${draft.text}`;publish.disabled=false;status.textContent='In review · Preview ready. Publish to this browser’s homepage sample.'};
publish.onclick=()=>{if(!draft)return;try{localStorage.setItem('camtran-demo-alert',JSON.stringify(draft));status.textContent='Published locally · Open the homepage to see the sample notice. No live service has changed.';publish.disabled=true}catch{status.textContent='Browser storage is unavailable. Sample was not saved.'}};
document.querySelector('#reset').onclick=()=>{try{localStorage.removeItem('camtran-demo-alert')}catch{}form.reset();preview.hidden=true;draft=null;publish.disabled=true;status.textContent='Reset · Default sample restored.'};
